import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Existing factory, owner-command and expiry consumers only; no player fields or new dispatch tree. */
public final class SummonOwnerMethods {
 static final String P="local/lito381/server/",H=P+"NativeSummonOwnerLifecycle",PC=P+"ClientSession",R=P+"NativeReturnNatureMaterialAction",T=R+"$Target";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class")).readAllBytes()).accept(c,ClassReader.SKIP_DEBUG);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static AbstractInsnNode prev(AbstractInsnNode i){do{i=i.getPrevious();}while(i!=null&&i.getOpcode()<0);return i;}
 static MethodNode method(ClassNode c,String name,String desc){return c.methods.stream().filter(m->m.name.equals(name)&&(desc==null||m.desc.equals(desc))).findFirst().orElseThrow();}
 static void patch(ClassNode c){
  if(c.name.equals(P+"GameHub")){if(c.fields.stream().anyMatch(f->f.name.equals("nativeSummonNextPhaseNanos")))throw new AssertionError("existing phase");c.fields.add(new FieldNode(ACC_PRIVATE|ACC_VOLATILE,"nativeSummonNextPhaseNanos","J",null,null));var m=method(c,"companionTickSafely","()V");var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new MethodInsnNode(INVOKESTATIC,H,"clock","(L"+P+"GameHub;)V",false));m.instructions.insert(x);return;}
  if(c.name.equals(T)){for(String f:List.of("nativeSummonOwnerContext","nativeSummonPublication"))if(c.fields.stream().anyMatch(v->v.name.equals(f)))throw new AssertionError("duplicate owner scope");c.fields.add(new FieldNode(ACC_PRIVATE,"nativeSummonOwnerContext","Z",null,null));c.fields.add(new FieldNode(ACC_PRIVATE,"nativeSummonPublication","Ljava/lang/Object;",null,null));return;}
  if(c.name.equals(R)){
   var original=method(c,"captureOutput",null);original.name="nativeSummonOriginalCaptureOutput";var m=new MethodNode(ASM9,ACC_STATIC,"captureOutput",original.desc,null,null);for(int n=0;n<3;n++)m.instructions.add(new VarInsnNode(ALOAD,n));m.instructions.add(new MethodInsnNode(INVOKESTATIC,H,"captureOutput",original.desc,false));m.instructions.add(new InsnNode(IRETURN));c.methods.add(m);
   m=new MethodNode(ASM9,ACC_STATIC,"ownerSlot","()Ljava/lang/ThreadLocal;",null,null);m.instructions.add(new FieldInsnNode(GETSTATIC,R,"current","Ljava/lang/ThreadLocal;"));m.instructions.add(new InsnNode(ARETURN));c.methods.add(m);
   m=new MethodNode(ASM9,ACC_STATIC,"ownerContext","(L"+PC+";L"+P+"BattleCompanion;L"+P+"NativeCompanionCallbacks$Stamp;)Ljava/lang/Object;",null,null);m.instructions.add(new TypeInsnNode(NEW,T));m.instructions.add(new InsnNode(DUP));m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new VarInsnNode(ALOAD,2));m.instructions.add(new MethodInsnNode(INVOKESPECIAL,T,"<init>","(L"+PC+";L"+PC+";L"+P+"BattleCompanion;L"+P+"NativeCompanionCallbacks$Stamp;)V",false));m.instructions.add(new InsnNode(DUP));m.instructions.add(new InsnNode(ICONST_1));m.instructions.add(new FieldInsnNode(PUTFIELD,T,"nativeSummonOwnerContext","Z"));m.instructions.add(new InsnNode(ARETURN));c.methods.add(m);
   m=new MethodNode(ASM9,ACC_STATIC,"ownerCanPublish","(Ljava/lang/Object;)Z",null,null);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new TypeInsnNode(CHECKCAST,T));m.instructions.add(new MethodInsnNode(INVOKEVIRTUAL,T,"canPublish","()Z",false));m.instructions.add(new InsnNode(IRETURN));c.methods.add(m);return;
  }
  int factories=0,commands=0,expiries=0,effects=0;
  for(var m:c.methods){
   if(m.name.equals("releaseCompanionToNature"))for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals(P+"Protocol")&&call.name.equals("effectObject")&&call.desc.equals("(JI)[B")){call.owner=H;effects++;}
   if(m.name.equals("createTamedCompanion")){for(var i:m.instructions.toArray())if(i.getOpcode()==ARETURN){var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new MethodInsnNode(INVOKESTATIC,H,"arm","(L"+P+"BattleCompanion;L"+PC+";)L"+P+"BattleCompanion;",false));m.instructions.insertBefore(i,x);}factories++;}
   int apply=0;for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals(P+"BattleCompanion")&&call.name.equals("apply")){
    if(!Set.of("hypertextAction","handleClassicWorldCompanionAction").contains(m.name))throw new AssertionError("unreviewed owner command "+m.name);var actionCall=prev(i);var requestLocal=prev(actionCall);if(!(actionCall instanceof MethodInsnNode actionMethod)||!actionMethod.name.equals("action")||!(requestLocal instanceof VarInsnNode requestVar)||requestVar.getOpcode()!=ALOAD)throw new AssertionError("native action request");var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,requestVar.var));m.instructions.insertBefore(i,x);m.instructions.set(i,new MethodInsnNode(INVOKESTATIC,H,"apply","(L"+P+"BattleCompanion;Ljava/lang/String;L"+PC+";L"+P+"Protocol$HypertextActionRequest;)L"+P+"BattleCompanion$CommandResult;",false));apply++;
   }
   if(apply!=0){if(apply!=1)throw new AssertionError("one apply per command");int guards=0;for(var i:m.instructions.toArray())if(i instanceof FieldInsnNode f&&f.owner.equals(P+"BattleCompanion$CommandResult")&&f.name.equals("DISMISSED")){
    var branch=i.getNext();while(branch!=null&&branch.getOpcode()<0)branch=branch.getNext();if(!(branch instanceof JumpInsnNode jump)||jump.getOpcode()!=IF_ACMPNE)continue;
    // Recover the owned local from the exact receiver before the replaced apply edge.
    MethodInsnNode port=null;for(var v:m.instructions)if(v instanceof MethodInsnNode q&&q.owner.equals(H)&&q.name.equals("apply"))port=q;var req=prev(port);var pc=prev(req);var action=prev(pc);var request=prev(action);var owned=prev(request);if(!(owned instanceof VarInsnNode own)||own.getOpcode()!=ALOAD)throw new AssertionError("owned command local");
    var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,own.var));x.add(new MethodInsnNode(INVOKESTATIC,H,"liberated","(L"+PC+";L"+P+"BattleCompanion;)Z",false));x.add(new JumpInsnNode(IFNE,jump.label));m.instructions.insert(branch,x);guards++;
   }if(guards!=1)throw new AssertionError("one dismissal tail guard "+m.name+" "+guards);commands++;}
   if(m.name.equals("serverClassicWorldCompanionTick")&&m.desc.equals("(IJ)V")||m.name.equals("serverCompanionTick")&&m.desc.equals("(JJ)V"))for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals(P+"BattleCompanion")&&call.name.equals("expired")){
    var time=prev(i);var actor=prev(time);if(!(time instanceof VarInsnNode clock)||clock.getOpcode()!=LLOAD||!(actor instanceof VarInsnNode pet)||pet.getOpcode()!=ALOAD)throw new AssertionError("expiry inputs");var branch=i.getNext();while(branch!=null&&branch.getOpcode()<0)branch=branch.getNext();if(!(branch instanceof JumpInsnNode skip)||skip.getOpcode()!=IFEQ)throw new AssertionError("expiry branch");LabelNode loop=null;for(var n=branch.getNext();n!=skip.label;n=n.getNext())if(n instanceof JumpInsnNode jump&&jump.getOpcode()==GOTO&&m.instructions.indexOf(jump.label)<m.instructions.indexOf(actor)){if(loop!=null&&loop!=jump.label)throw new AssertionError("ambiguous expiry continuation");loop=jump.label;}if(loop==null)throw new AssertionError("expiry continuation");var x=new InsnList();x.add(new VarInsnNode(ALOAD,pet.var));x.add(new VarInsnNode(LLOAD,clock.var));x.add(new VarInsnNode(ALOAD,0));x.add(new MethodInsnNode(INVOKESTATIC,H,"expiry","(L"+P+"BattleCompanion;JL"+PC+";)Z",false));x.add(new JumpInsnNode(IFNE,loop));m.instructions.insertBefore(actor,x);expiries++;
   }
  }if(factories!=3||commands!=2||expiries!=2||effects!=2)throw new AssertionError("exact factory/command/expiry ports "+factories+"/"+commands+"/"+expiries);
 }
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[1])){for(String owner:List.of(PC,P+"GameHub",R,T)){var c=read(old,owner);patch(c);var expected=bytes(c);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(owner+".class");Files.createDirectories(p.getParent());Files.write(p,expected);}else try(var next=new JarFile(a[2])){if(!Arrays.equals(expected,bytes(read(next,owner))))throw new AssertionError("exact owner lifecycle regeneration "+owner);}}System.out.println("PASS exact Source phase, three existing factories, two existing owner commands and two existing expiry consumers; existing spell dispatch and bodies retained");}}
}
